"use client";
import{useCallback,useEffect,useMemo,useState}from"react";
import Link from"next/link";
import{AppShell}from"../../ui/app-shell";
import{getSupabaseBrowserClient}from"../../../lib/supabase/client";
import{usePlayerData}from"../../../lib/use-player-data";
import{summarise,type TrackmanShotRow}from"../../../lib/trackman-analysis";
import"../../trackman-diagnose.css";
type Player={id:string;display_name:string|null;email:string};type Session={id:string;title:string;session_date:string|null;test_type:string;trackman_shots:TrackmanShotRow[]};type Item={id:string;code:string;title:string;item_type:"golf_drill"|"vector_exercise";purpose:string};type Rec={id:string;library_item_id:string;recommendation_role:string;library_items:Item|null};type Case={id:string;trackman_session_id:string;trackman_club:string|null;status:string;confidence:string;observation:string;impact_family:string|null;supported_cause_test:string|null;coach_diagnosis:string|null;player_explanation:string|null;evidence_snapshot:Record<string,unknown>;case_recommendations:Rec[];diagnostic_case_versions:{id:number;changed_at:string}[]};
const shotFields="id,session_id,source_row,club,ball_speed,club_speed,smash_factor,carry,total,launch_angle,launch_direction,spin_rate,spin_axis,height,landing_angle,curve,side_distance,face_angle,club_path,face_to_path,attack_angle,dynamic_loft,spin_loft,low_point,swing_plane,swing_direction,impact_height,impact_offset";
const impactFamilies=["centred","heel","toe","high","low","variable","not_available"];
export default function TrackmanDiagnose(){const{profile}=usePlayerData();const canCoach=profile?.role==="coach"||profile?.role==="admin";const[players,setPlayers]=useState<Player[]>([]);const[playerId,setPlayerId]=useState("");const[sessions,setSessions]=useState<Session[]>([]);const[sessionId,setSessionId]=useState("");const[club,setClub]=useState("all");const[cases,setCases]=useState<Case[]>([]);const[activeId,setActiveId]=useState("");const[library,setLibrary]=useState<Item[]>([]);const[query,setQuery]=useState("");const[message,setMessage]=useState("");
 const loadPlayers=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!canCoach)return;const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(row=>row.player_id);if(!ids.length)return;const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids).order("display_name");const rows=(data||[])as Player[];setPlayers(rows);setPlayerId(value=>value||rows[0]?.id||"");},[profile,canCoach]);
 const loadWorkspace=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!playerId)return;const[sessionResult,caseResult,itemResult]=await Promise.all([sb.from("trackman_sessions").select(`id,title,session_date,test_type,trackman_shots(${shotFields})`).eq("player_id",playerId).order("session_date",{ascending:false,nullsFirst:false}),sb.from("diagnostic_cases").select("id,trackman_session_id,trackman_club,status,confidence,observation,impact_family,supported_cause_test,coach_diagnosis,player_explanation,evidence_snapshot,case_recommendations(id,library_item_id,recommendation_role,library_items(id,code,title,item_type,purpose)),diagnostic_case_versions(id,changed_at)").eq("player_id",playerId).eq("source_type","trackman").order("created_at",{ascending:false}),sb.from("library_items").select("id,code,title,item_type,purpose").eq("status","approved").eq("player_ready",true).order("code")]);if(sessionResult.error||caseResult.error){setMessage(sessionResult.error?.message||caseResult.error?.message||"Could not load TrackMan reviews.");return;}const rows=(sessionResult.data||[])as unknown as Session[];setSessions(rows);setSessionId(value=>rows.some(item=>item.id===value)?value:rows[0]?.id||"");setCases((caseResult.data||[])as unknown as Case[]);setLibrary((itemResult.data||[])as Item[]);},[playerId]);
 useEffect(()=>{const timer=setTimeout(()=>void loadPlayers(),0);return()=>clearTimeout(timer)},[loadPlayers]);useEffect(()=>{const timer=setTimeout(()=>void loadWorkspace(),0);return()=>clearTimeout(timer)},[loadWorkspace]);
 const selected=sessions.find(item=>item.id===sessionId);const clubs=useMemo(()=>Array.from(new Set((selected?.trackman_shots||[]).map(item=>item.club).filter(Boolean)as string[])).sort(),[selected]);const shots=useMemo(()=>club==="all"?(selected?.trackman_shots||[]):(selected?.trackman_shots||[]).filter(item=>item.club===club),[selected,club]);const metrics=useMemo(()=>summarise(shots),[shots]);const metric=(key:string)=>metrics.find(item=>item.key===key);const active=cases.find(item=>item.id===activeId);const filtered=library.filter(item=>`${item.code} ${item.title} ${item.purpose}`.toLowerCase().includes(query.toLowerCase())).slice(0,10);
 const createReview=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!selected||!shots.length)return;const confidence=shots.length<5?"insufficient":shots.length<10?"emerging":shots.length<20?"moderate":"strong";const score=Math.min(95,Math.round(shots.length/20*100));const offline=metric("side_distance"),carry=metric("carry"),facePath=metric("face_to_path");const observation=`${shots.length} ${club==="all"?"selected":club} shots · carry ${carry?.mean??"—"} · offline SD ${offline?.sd??"—"} · face-to-path SD ${facePath?.sd??"—"}`;const snapshot={captured_at:new Date().toISOString(),session:{id:selected.id,title:selected.title,date:selected.session_date,test_type:selected.test_type},club,shot_ids:shots.map(item=>item.id),shot_count:shots.length,metrics:Object.fromEntries(metrics.map(item=>[item.key,{mean:item.mean,sd:item.sd,count:item.count,unit:item.unit}]))};const{data,error}=await sb.from("diagnostic_cases").insert({player_id:playerId,shot_band:`TrackMan · ${club==="all"?"all clubs":club}`,status:"draft",confidence,confidence_score:score,priority_score:0,opportunities:shots.length,successes:0,pattern_key:"trackman_session",observation,interpretation:"Measured TrackMan pattern awaiting coach-led cause testing.",evidence_summary:observation,next_test:"Record the comparison test that would support or challenge the working hypothesis.",guardrail:"TrackMan delivery and flight measurements do not independently prove a swing or physical cause.",coach_note:null,created_by:profile.id,source_type:"trackman",trackman_session_id:selected.id,trackman_club:club,evidence_snapshot:snapshot,impact_family:"not_available"}).select("id").single();setMessage(error?error.message:"Draft TrackMan review created.");if(data){setActiveId(data.id);await loadWorkspace();}};
 const update=async(changes:Record<string,unknown>)=>{const sb=getSupabaseBrowserClient();if(!sb||!active)return;const{error}=await sb.from("diagnostic_cases").update(changes).eq("id",active.id);setMessage(error?error.message:"Review saved.");if(!error)await loadWorkspace();};const decide=async(status:"approved"|"rejected"|"superseded")=>{const sb=getSupabaseBrowserClient();if(!sb||!active)return;const{error}=await sb.rpc("review_trackman_case",{target_case:active.id,new_status:status});setMessage(error?error.message:`Review ${status}.`);if(!error)await loadWorkspace();};const add=async(item:Item)=>{const sb=getSupabaseBrowserClient();if(!sb||!active)return;const role=item.item_type==="vector_exercise"?"physical_support":"practice";const{error}=await sb.from("case_recommendations").insert({case_id:active.id,library_item_id:item.id,sequence:(active.case_recommendations?.length||0)+1,recommendation_role:role,rationale:role==="physical_support"?"Coach-selected physical support following movement assessment.":"Coach-selected practice prescription following the supported comparison test."});setMessage(error?error.message:`${item.code} assigned.`);setQuery("");if(!error)await loadWorkspace();};const remove=async(id:string)=>{const sb=getSupabaseBrowserClient();if(!sb)return;const{error}=await sb.from("case_recommendations").delete().eq("id",id);setMessage(error?error.message:"Item removed.");if(!error)await loadWorkspace();};
 if(profile&&!canCoach)return <AppShell active="trackman"><div className="empty-state"><h2>Coach access required</h2><p>This diagnostic workspace is available only to approved coaches.</p></div></AppShell>;
 return <AppShell active="trackman"><header className="page-heading"><div><p className="eyebrow">Package 7G.3 · TrackMan diagnosis</p><h1>Evidence, test, decision.</h1><p>Freeze the measured pattern, test the working cause and publish only the explanation and prescription you can support.</p></div><div className="tm-heading-actions"><Link className="secondary-action" href="/trackman/analysis">Analysis</Link><Link className="secondary-action" href="/trackman">Import</Link></div></header>{message&&<div className="success-banner">{message}</div>}<section className="tm-diagnostic-controls"><label>Player<select value={playerId} onChange={event=>{setPlayerId(event.target.value);setActiveId("")}}>{players.map(item=><option value={item.id} key={item.id}>{item.display_name||item.email}</option>)}</select></label><label>Evidence session<select value={sessionId} onChange={event=>{setSessionId(event.target.value);setClub("all")}}>{sessions.map(item=><option value={item.id} key={item.id}>{item.session_date||"No date"} · {item.title}</option>)}</select></label><label>Club<select value={club} onChange={event=>setClub(event.target.value)}><option value="all">All clubs</option>{clubs.map(item=><option key={item}>{item}</option>)}</select></label><button className="primary-action" disabled={!shots.length} onClick={createReview}>Freeze evidence and review</button></section>
 <div className="tm-diagnostic-layout"><aside className="tm-case-list"><p className="eyebrow">TrackMan reviews</p>{cases.map(item=><button className={activeId===item.id?"active":""} onClick={()=>setActiveId(item.id)} key={item.id}><strong>{item.trackman_club||"All clubs"}</strong><span>{item.observation}</span><small>{item.status} · {item.confidence} · {item.diagnostic_case_versions?.length||0} versions</small></button>)}{!cases.length&&<p className="empty-copy">Freeze a session evidence set to begin.</p>}</aside><section className="tm-diagnostic-editor">{!active?<div className="empty-state compact"><h2>Select a review</h2><p>Open an existing review or freeze the selected evidence into a new one.</p></div>:<><header><div><p className="eyebrow">Immutable evidence snapshot</p><h2>{active.observation}</h2></div><span className={`case-state ${active.status}`}>{active.status}</span></header><div className="snapshot-grid"><div><span>Shots</span><strong>{String(active.evidence_snapshot?.shot_count??"—")}</strong></div><div><span>Club</span><strong>{active.trackman_club||"All"}</strong></div><div><span>Evidence</span><strong>{active.confidence}</strong></div><div><span>Versions</span><strong>{active.diagnostic_case_versions?.length||0}</strong></div></div><div className="diagnostic-fields"><label>Impact family<select value={active.impact_family||"not_available"} onChange={event=>update({impact_family:event.target.value})}>{impactFamilies.map(item=><option value={item} key={item}>{item.replace("_"," ")}</option>)}</select></label><label>Supported cause test<textarea defaultValue={active.supported_cause_test||""} onBlur={event=>update({supported_cause_test:event.target.value})} placeholder="Describe the comparison test and the result that supported or challenged the hypothesis."/></label><label>Coach diagnosis<textarea defaultValue={active.coach_diagnosis||""} onBlur={event=>update({coach_diagnosis:event.target.value})} placeholder="Record the coach's concluded priority—not an automatic TrackMan inference."/></label><label>Player-facing explanation<textarea defaultValue={active.player_explanation||""} onBlur={event=>update({player_explanation:event.target.value})} placeholder="Explain what was measured, what the test showed and what the player should work on."/></label></div><div className="tm-prescription"><h3>Prescription</h3>{active.case_recommendations?.map(rec=><div key={rec.id}><span><b>{rec.library_items?.code}</b>{rec.library_items?.title}<small>{rec.recommendation_role.replace("_"," ")}</small></span><button onClick={()=>remove(rec.id)}>Remove</button></div>)}<div className="tm-library-search"><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search player-ready drills and Vector exercises"/>{query&&<div>{filtered.map(item=><button key={item.id} onClick={()=>add(item)}><b>{item.code}</b><span>{item.title}</span></button>)}</div>}</div></div><div className="tm-decision-actions"><button onClick={()=>decide("rejected")}>Reject</button><button onClick={()=>decide("superseded")}>Supersede</button><button className="primary-action" onClick={()=>decide("approved")}>Approve for player</button></div></>}</section></div></AppShell>;
}
